/**
 * The glossary, on `src/api/schema.d.ts` — generated by `make types` from the
 * real pydantic models and held to the tree by `make lint-generated`.
 *
 * `LookupView` hand-declared these four and was missing SIX fields the server
 * has been sending on every row: `attempt_count`, `confidence`, `decided_at`,
 * `entity_id`, `last_attempt_at` and `last_attempt_run_id`. That is the same
 * failure `types/curation.ts` records for `DefinitionQueue` and `decided`, and
 * it is why hand-declaring a wire shape is not a shortcut.
 *
 * It also got the OPTIONALITY wrong in three places, which is the half that
 * bites at runtime rather than in review: `grounding`, `GlossaryList.items` /
 * `.counts` and `GlossarySurface.entries` are all optional on the model and were
 * declared required. A type that says a field is always there does not make it
 * always there.
 *
 * See contract C9 on generated artifacts.
 */

import type { components } from '@/api/schema'

type Schemas = components['schemas']

/**
 * Where a definition came from. Empty on an undefined row -- which is the
 * common case, not the edge case, so this is optional on `GlossaryEntry` and
 * every read of it has to say what it does when there is nothing.
 *
 * `types/brief.ts` exports a `Grounding` too; they are different models
 * (`Grounding` vs `GlossaryGrounding`) and both are real. Named distinctly here
 * rather than aliased to the shorter name, because the two shapes met in this
 * view and one of them silently won.
 */
export type GlossaryGrounding = Schemas['GlossaryGrounding']

/** One row of the review queue. */
export type GlossaryEntry = Schemas['GlossaryEntry']

/** `GET /glossary`. */
export type GlossaryList = Schemas['GlossaryList']

/** `GET /glossary/{surface}` — every accepted reading of one surface. */
export type GlossarySurface = Schemas['GlossarySurface']


/** `POST /glossary/{surface}/lookup` — `RunStarted` plus the surface it is for.
 *  A lookup is a run, not a request; see `docs/adr/`. */
export type LookupStarted = Schemas['LookupStarted']
